// The photo gallery, in the repo rather than in a database.
//
// This file is the single source of truth for every photo the public site shows:
// which file, how big it is, what it says to a screen reader, and what the caption
// under it reads. Alt text and captions are reviewable text in a diff, and the
// image weights are decided at commit time instead of at upload time.
//
// The full-resolution originals live in the owner's Google Drive. To add a photo:
//   1. Keep the original in Drive.
//   2. Copy it into images-src/ (gitignored) named as the public slug —
//      lowercase, hyphenated, ASCII, e.g. front-porch-morning.jpg
//   3. `node scripts/optimize-images.mjs` — writes public/gallery/<slug>.jpg and
//      prints an entry with width, height and blurDataURL already filled in.
//   4. Paste the entry below, write `alt` and `caption`, and commit both the
//      derivative and this file.
//
// `src` values are stable public paths on purpose: they are emitted as absolute
// URLs in the home page's JSON-LD, so a hashed bundler URL (a static `import`)
// would churn the structured data on every rebuild.
//
// src/content/gallery.test.ts enforces the invariants — files exist, dimensions
// are true, ids are unique, alt is present, and the copy still matches
// docs/gallery-export.json.

/** Where the home page uses a photo. Each role belongs to exactly one photo. */
export type GalleryRole = "hero" | "intro";

export interface GalleryPhoto {
  /** Stable slug. Also the basename of the file in public/gallery/. */
  id: string;
  /** Public path, served straight from public/. Never a bundler import. */
  src: string;
  /** Intrinsic size of the committed file — next/image needs both to reserve space. */
  width: number;
  height: number;
  /**
   * What a screen reader announces. Required. A photo that carries no information
   * of its own gets `alt: ""` *and* `decorative: true`, so an empty string is
   * always a deliberate choice rather than an omission.
   */
  alt: string;
  /** Shown under the photo in the lightbox. Never a duplicate of `alt`. */
  caption: string;
  /** Display order, ascending. Carried over from the old database sort_order. */
  order: number;
  /** Inline LQIP, generated by scripts/optimize-images.mjs. */
  blurDataURL: string;
  /** Marks this photo as the home page's hero or intro image. */
  role?: GalleryRole;
  /** Only with `alt: ""` — states that the empty alt text is intentional. */
  decorative?: true;
}

// The annotation is what makes an entry missing `alt` (or any other required
// field) a compile error, and it keeps the optional `role` / `decorative` fields
// visible to consumers. `satisfies` is kept alongside it so the error points at
// the offending entry rather than at the whole array.
