/** The one photo that fills a named slot on the home page. */
export function photoForRole(role: GalleryRole): GalleryPhoto {
  const match = GALLERY.filter((p) => p.role === role);
  if (match.length !== 1) {
    // A build-time mistake, not a runtime condition — fail loudly rather than
    // silently rendering the wrong photo (or none) on the most important page.
    throw new Error(`Expected exactly one gallery photo with role "${role}", found ${match.length}`);
  }
  return match[0];
}
